// Algorithm for sorting an array of words

// Define a function to sort an array of words
function sortWords(arr) {
  // Create an empty array to store the sorted words
  let sortedWords = [];

  // Loop through the array of words
  for (let I = 0; I < arr.length; i++) {

    // Loop through the words in the array
    for (let j = I + 1; j < arr.length; j++) {

      // Compare the words at the current and next indices
      if (arr[i] < arr[j]) {
        // If the current word is less than the next word, swap them
        sortedWords.push(arr[i]);
        sortedWords.push(arr[j]);
        // Update the indices
        i++;
        j++;
      }
    }
  }

  // Return the sorted words
  return sortedWords;
}

